package net.nicomar.nomoregrids.platform;

import java.io.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.MoverType;
import net.minecraft.world.entity.vehicle.minecart.AbstractMinecart;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;
import net.nicomar.nomoregrids.core.*;
import net.nicomar.nomoregrids.geometry.*;
import net.nicomar.nomoregrids.operation.OperationPlan;
import net.nicomar.nomoregrids.persistence.NativeStateImage;
import net.nicomar.nomoregrids.simulation.movement.*;

/** Native and converted rails share exact endpoint continuity; no host-based rail snapping. */
public final class WorldRails {
    public static final String ADAPTER="nomoregrids:rail";
    private record Track(PieceRecord piece,RailPath path,boolean converted){}
    private WorldRails(){}
    private static final Map<WorldService,Integer> CURSORS=new WeakHashMap<>();
    public static boolean detector(PieceRecord p){return piece(p)&&p.sourceBlockId().value().equals("minecraft:detector_rail");}
    public static boolean piece(PieceRecord p){return p.adapterId().value().equals(ADAPTER);}
    public static boolean eligible(BlockState s){return Set.of("minecraft:rail","minecraft:powered_rail","minecraft:detector_rail","minecraft:activator_rail").contains(BuiltInRegistries.BLOCK.getKey(s.getBlock()).toString());}
    public static PieceRecord capture(BlockState s,BlockGetter world,BlockPos at,UUID id){if(!eligible(s))throw new IllegalArgumentException("UNSUPPORTED_ADAPTER: rail");var source=new ResourceId(BuiltInRegistries.BLOCK.getKey(s.getBlock()).toString());var shape=NativeStates.boxes(s.getShape(world,at));return new PieceRecord(id,0,new ResourceId(ADAPTER),1,source,NativeStates.properties(s),new GridPoint(at.getX()*16L,at.getY()*16L,at.getZ()*16L),0,GridPoint.BLOCK_CENTER,new BoxGeometrySnapshot(shape,NativeStates.boxes(s.getCollisionShape(world,at)),shape),new NativeStateImage(source,NativeStates.properties(s)).encode(),BinaryData.EMPTY,BinaryData.EMPTY,Optional.empty(),Set.of());}
    public static RailPath path(PieceRecord p){return new RailPath(p.sourceState().get("shape"),p.orientation(),p.pivot16(),p.origin16());}
    public static BlockState placement(Block block,net.minecraft.world.item.context.BlockPlaceContext context){var state=block.getStateForPlacement(context);if(state==null)state=block.defaultBlockState();var values=new HashMap<>(NativeStates.properties(state));values.put("shape",context.getHorizontalDirection().getAxis()==Direction.Axis.X?"east_west":"north_south");values.put("waterlogged","false");return NativeStates.resolve(new ResourceId(BuiltInRegistries.BLOCK.getKey(block).toString()),values);}
    private static List<PieceRecord> alternatives(PieceRecord p,BlockGetter world){var result=new ArrayList<PieceRecord>();result.add(p);for(var shape:net.minecraft.world.level.block.state.properties.RailShape.values()){
        var s=NativeStates.resolve(p);if(!((BaseRailBlock)s.getBlock()).isValidRailShape(shape))continue;var values=new HashMap<>(p.sourceState());values.put("shape",shape.getSerializedName());if(values.equals(p.sourceState()))continue;var state=NativeStates.resolve(p.sourceBlockId(),values);var geometry=capture(state,world,WorldService.pos(p.origin16().cell()),p.pieceId()).geometry();result.add(new PieceRecord(p.pieceId(),p.revision(),p.adapterId(),1,p.sourceBlockId(),values,p.origin16(),p.orientation(),p.pivot16(),geometry,p.geometryPayload(),p.materialPayload(),p.itemPayload(),p.groupId(),p.flags()));
    }return result;}
    private static int links(PieceRecord p,Collection<PieceRecord> neighbors,boolean potential,BlockGetter world){int result=0;var route=path(p);for(boolean end:new boolean[]{false,true}){boolean found=false;for(var q:neighbors){if(q.pieceId().equals(p.pieceId()))continue;for(var alternative:potential?alternatives(q,world):List.of(q))for(boolean side:new boolean[]{false,true})if(RailConnections.continuous(route.endpoint(end),path(alternative).endpoint(side))){found=true;break;}if(found)break;}if(found)result++;}return result;}
    public static OperationPlan prepare(WorldService service,OperationPlan plan){
        if(plan.changes().stream().noneMatch(c->c.before().filter(WorldRails::piece).isPresent()||c.after().filter(WorldRails::piece).isPresent()))return plan;var index=service.snapshot();var work=new HashMap<>(index.records());var occupancyDelta=new HashMap<CellPos,Integer>();var sources=new HashMap<UUID,CellPos>();for(var c:plan.changes()){var old=work.get(c.id());if(old!=null)for(var cell:old.worldOccupation().cells(8))occupancyDelta.merge(cell,-1,Integer::sum);if(c.after().isPresent()){var next=c.after().orElseThrow();work.put(c.id(),next);for(var cell:next.worldOccupation().cells(8))occupancyDelta.merge(cell,1,Integer::sum);}else work.remove(c.id());c.nativeSource().ifPresent(pos->sources.put(c.id(),pos));}var touched=plan.pieceCells();var nearby=new LinkedHashMap<UUID,PieceRecord>();for(var p:work.values())if(piece(p)&&p.worldOccupation().cells(8).stream().anyMatch(c->touched.stream().anyMatch(t->Math.abs(t.x()-c.x())+Math.abs(t.y()-c.y())+Math.abs(t.z()-c.z())<=2)))nearby.put(p.pieceId(),p);
        var nativeCells=new HashSet<CellPos>();for(var p:List.copyOf(nearby.values()))for(var c:p.worldOccupation().cells(8))for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++){
            var neighbor=new CellPos(c.x()+x,c.y()+y,c.z()+z);if(!nativeCells.add(neighbor)||index.at(neighbor).size()+occupancyDelta.getOrDefault(neighbor,0)>0)continue;var pos=WorldService.pos(neighbor);if(!service.level().isLoaded(pos))continue;var state=WorldNativeView.at(neighbor).orElseGet(()->service.level().getBlockState(pos));if(!eligible(state))continue;var nativePiece=capture(state,service.level(),pos,UUID.randomUUID());boolean current=links(nativePiece,List.of(p),false,service.level())>0;if(current)continue;if(alternatives(nativePiece,service.level()).stream().noneMatch(candidate->links(candidate,List.of(p),true,service.level())>0))continue;
            work.put(nativePiece.pieceId(),nativePiece);for(var cell:nativePiece.worldOccupation().cells(8))occupancyDelta.merge(cell,1,Integer::sum);nearby.put(nativePiece.pieceId(),nativePiece);sources.put(nativePiece.pieceId(),neighbor);
        }
        for(int pass=0;pass<8;pass++){boolean changed=false;for(var p:List.copyOf(nearby.values())){var neighbors=new ArrayList<PieceRecord>(nearby.values());var nativeNeighbors=tracks(service.level(),new Vec3(p.origin16().x()/16.0,p.origin16().y()/16.0,p.origin16().z()/16.0));for(var nativeTrack:nativeNeighbors)if(!nativeTrack.converted&&sources.values().stream().noneMatch(c->c.equals(nativeTrack.piece.origin16().cell())))neighbors.add(nativeTrack.piece);var best=p;int score=links(p,neighbors,false,service.level());for(var candidate:alternatives(p,service.level())){int candidateScore=links(candidate,neighbors,false,service.level());if(candidateScore>score){best=candidate;score=candidateScore;}}if(!best.sourceState().equals(p.sourceState())){nearby.put(p.pieceId(),best);work.put(p.pieceId(),best);changed=true;}}if(!changed)break;}
        var changes=new ArrayList<>(plan.changes());for(var entry:nearby.entrySet()){var id=entry.getKey();var p=entry.getValue();var original=service.snapshot().records().get(id);var already=changes.stream().filter(c->c.id().equals(id)).findFirst();if(original!=null&&original.sourceState().equals(p.sourceState())&&already.isEmpty())continue;long revision=original==null?0:original.revision()+1;var next=new PieceRecord(id,revision,p.adapterId(),1,p.sourceBlockId(),p.sourceState(),p.origin16(),p.orientation(),p.pivot16(),p.geometry(),p.geometryPayload(),p.materialPayload(),p.itemPayload(),p.groupId(),p.flags());changes.removeIf(c->c.id().equals(id));changes.add(new OperationPlan.Change(id,Optional.ofNullable(original),Optional.of(next),Optional.ofNullable(sources.get(id))));}
        return new OperationPlan(plan.id(),plan.actor(),plan.kind(),changes,plan.resourcesBefore(),plan.resourcesAfter(),plan.effects());
    }
    public static Optional<PieceRecord> selected(net.minecraft.world.item.context.UseOnContext context){var player=context.getPlayer();if(player==null||!(context.getLevel().getBlockEntity(context.getClickedPos()) instanceof net.nicomar.nomoregrids.world.CompositeCellEntity cell)||!cell.valid())return Optional.empty();return ComponentSelection.select(player,cell.view(),0).filter(WorldRails::piece).filter(p->Direction6.UP.rotated(p.orientation())==Direction6.UP&&!p.flags().contains(PieceRecord.Flag.SUBSTITUTE));}
    private static List<Track> tracks(Level level,Vec3 point){var result=new LinkedHashMap<UUID,Track>();var center=BlockPos.containing(point);for(int x=-2;x<=2;x++)for(int y=-2;y<=1;y++)for(int z=-2;z<=2;z++){var at=center.offset(x,y,z);if(!level.isLoaded(at))continue;var cell=new CellPos(at.getX(),at.getY(),at.getZ());if(level.getBlockEntity(at) instanceof net.nicomar.nomoregrids.world.CompositeCellEntity be){for(var p:be.view().replicas())if(piece(p)&&!p.flags().contains(PieceRecord.Flag.SUBSTITUTE)&&Direction6.UP.rotated(p.orientation())==Direction6.UP)result.putIfAbsent(p.pieceId(),new Track(p,path(p),true));}else{var state=level.getBlockState(at);if(eligible(state)){var id=UUID.nameUUIDFromBytes((level.dimension().identifier()+"|rail|"+at.asLong()).getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=capture(state,level,at,id);result.put(id,new Track(p,path(p),false));}}}return List.copyOf(result.values());}
    public static boolean tick(AbstractMinecart cart){if(!(cart.level() instanceof ServerLevel level))return false;var service=NmgRuntime.existing(level);if(service==null||service.quarantined())return false;var tracks=tracks(level,cart.position());if(tracks.stream().noneMatch(Track::converted))return false;var point=new ConvexVolume.Vec(cart.getX()*16,cart.getY()*16,cart.getZ()*16);Track current=null;double at=0,best=Double.POSITIVE_INFINITY;for(var track:tracks){double t=track.path.nearest(point),distance=track.path.sample(t).position().sub(point).length();if(distance<best){best=distance;current=track;at=t;}}if(current==null||best>8)return false;
        var direction=current.path.sample(at).tangent();var velocity=cart.getDeltaMovement();double signed=(velocity.x*direction.x()+velocity.y*direction.y()+velocity.z*direction.z());int sign=signed<0?-1:1;double speed=Math.min(cart.getBehavior().getMaxSpeed(level),Math.abs(signed));if(speed<0.01&&cart.getControllingPassenger()!=null){var input=cart.getControllingPassenger().getDeltaMovement();double push=input.x*direction.x()+input.z*direction.z();if(Math.abs(push)>0.01){sign=push<0?-1:1;speed=0.1;}}
        speed=Math.max(0,speed-sign*direction.y()*0.04);if(current.piece.sourceBlockId().value().equals("minecraft:powered_rail")){if(Boolean.parseBoolean(current.piece.sourceState().get("powered")))speed=Math.min(cart.getBehavior().getMaxSpeed(level),speed+0.06);else speed=speed<0.03?0:speed*0.5;}
        double remaining=speed*16;for(int step=0;step<16&&remaining>1e-8;step++){double distance=current.path.distance(at),available=sign>0?current.path.length()-distance:distance;if(remaining<=available+1e-8){at=current.path.parameter(distance+sign*remaining);remaining=0;break;}remaining-=available;var end=current.path.endpoint(sign>0);Track next=null;boolean nextEnd=false;for(var candidate:tracks){if(candidate.piece.pieceId().equals(current.piece.pieceId()))continue;for(boolean endpoint:new boolean[]{false,true})if(RailConnections.continuous(end,candidate.path.endpoint(endpoint))){if(next!=null){speed=0;remaining=0;break;}next=candidate;nextEnd=endpoint;}if(remaining==0)break;}if(next==null){at=sign>0?1:0;speed=0;remaining=0;break;}current=next;at=nextEnd?1:0;sign=nextEnd?-1:1;}
        var sample=current.path.sample(at);var target=new Vec3(sample.position().x()/16,sample.position().y()/16,sample.position().z()/16);var before=cart.position();cart.setOnRails(true);cart.move(MoverType.SELF,target.subtract(before));if(cart.position().distanceToSqr(target)>1e-8)speed=0;double drag=cart.getBehavior().getSlowdownFactor();if(cart.isInWater())drag*=0.95;var tangent=sample.tangent().scale(sign*speed*drag);cart.setDeltaMovement(tangent.x(),tangent.y(),tangent.z());cart.setYRot((float)Math.toDegrees(Math.atan2(-tangent.x(),tangent.z())));cart.setXRot((float)-Math.toDegrees(Math.atan2(tangent.y(),Math.hypot(tangent.x(),tangent.z()))));cart.fallDistance=0;cart.getBehavior().pushAndPickupEntities();cart.applyEffectsFromBlocks();
        if(cart.getBehavior() instanceof net.minecraft.world.entity.vehicle.minecart.NewMinecartBehavior behavior)behavior.lerpSteps.add(new net.minecraft.world.entity.vehicle.minecart.NewMinecartBehavior.MinecartStep(cart.position(),cart.getDeltaMovement(),cart.getYRot(),cart.getXRot(),(float)Math.max(0.001,cart.position().distanceTo(before))));
        if(current.piece.sourceBlockId().value().equals("minecraft:activator_rail"))cart.activateMinecart(level,WorldService.pos(current.piece.origin16().cell()).getX(),WorldService.pos(current.piece.origin16().cell()).getY(),WorldService.pos(current.piece.origin16().cell()).getZ(),Boolean.parseBoolean(current.piece.sourceState().get("powered")));return true;
    }
    private record Search(PieceRecord piece,int length){}
    private static boolean powered(WorldService service,PieceRecord p){var pending=new ArrayDeque<Search>();pending.add(new Search(p,0));var seen=new HashSet<UUID>();while(!pending.isEmpty()){var entry=pending.removeFirst();if(!seen.add(entry.piece.pieceId())||entry.length>8)continue;if(service.circuits().power(entry.piece)>0)return true;var route=path(entry.piece);for(var next:tracks(service.level(),new Vec3(entry.piece.origin16().x()/16.0,entry.piece.origin16().y()/16.0,entry.piece.origin16().z()/16.0))){if(!next.piece.sourceBlockId().equals(p.sourceBlockId()))continue;boolean connected=false;for(boolean a:new boolean[]{false,true})for(boolean b:new boolean[]{false,true})if(RailConnections.continuous(route.endpoint(a),next.path.endpoint(b)))connected=true;if(!connected)continue;if(!next.converted&&Boolean.parseBoolean(next.piece.sourceState().get("powered")))return true;pending.add(new Search(next.piece,entry.length+1));}}return false;}
    public static int analog(ServerLevel level,PieceRecord p){var b=p.worldOccupation().bounds();int value=0;for(var cart:level.getEntitiesOfClass(AbstractMinecart.class,new net.minecraft.world.phys.AABB(b.min().x()/16.0,b.min().y()/16.0,b.min().z()/16.0,b.max().x()/16.0,b.max().y()/16.0+1,b.max().z()/16.0)))if(cart instanceof net.minecraft.world.Container container)value=Math.max(value,net.minecraft.world.inventory.AbstractContainerMenu.getRedstoneSignalFromContainer(container));return value;}
    public static void tick(WorldService service)throws IOException{var rails=service.snapshot().ticked(ADAPTER);for(int turn=0;turn<Math.min(64,rails.size());turn++){int cursor=CURSORS.getOrDefault(service,0);var p=rails.get(Math.floorMod(cursor,rails.size()));CURSORS.put(service,Math.floorMod(cursor+1,rails.size()));if(p.worldOccupation().cells(8).stream().anyMatch(c->!service.level().isLoaded(WorldService.pos(c))))continue;var values=new HashMap<>(p.sourceState());if(!values.containsKey("powered"))continue;boolean powered;if(p.sourceBlockId().value().equals("minecraft:detector_rail")){var b=p.worldOccupation().bounds();powered=!service.level().getEntitiesOfClass(AbstractMinecart.class,new net.minecraft.world.phys.AABB(b.min().x()/16.0,b.min().y()/16.0,b.min().z()/16.0,b.max().x()/16.0,b.max().y()/16.0+1,b.max().z()/16.0)).isEmpty();}else powered=powered(service,p);if(powered==Boolean.parseBoolean(values.get("powered")))continue;values.put("powered",Boolean.toString(powered));var next=new PieceRecord(p.pieceId(),p.revision()+1,p.adapterId(),1,p.sourceBlockId(),values,p.origin16(),p.orientation(),p.pivot16(),p.geometry(),p.geometryPayload(),p.materialPayload(),p.itemPayload(),p.groupId(),p.flags());service.executeWorld(List.of(new OperationPlan.Change(p.pieceId(),Optional.of(p),Optional.of(next))),List.of());}}
}
